async def act(page):
    """
    From the current storefront page, navigate to the Magento Admin order view for order 299 and click the Cancel control.

    Approach:
    - Try a direct relative navigation to the order view URL for order_id 299.
    - If the Cancel control is not present there, go to the Orders grid and locate order 299 (link or row) and navigate to its view via href when possible.
    - On the order view, locate the Cancel control (scope under the document role where possible) and click it as the final action.
    - If a non-navigation confirmation button appears (modal), click it as the final action.

    Notes:
    - Do NOT change language settings.
    - All element lookups use accessibility-role based selectors (page.get_by_role and .filter(has=...)).
    - There are no knowledge-base helper functions available in the environment, so none are used.
    """
    # Explicit reasoning about knowledge-base functions: none are available in the provided environment; their utility is nil.

    async def nav_and_wait(url: str):
        await page.goto(url)
        await page.wait_for_load_state("networkidle")

    async def find_cancel_control_scoped():
        # Prefer scoping via the document role to reduce ambiguity
        try:
            doc = page.get_by_role("document")
            if await doc.count() > 0:
                btn = doc.get_by_role("button", name="Cancel")
                if await btn.count() > 0:
                    return btn.first()
                lnk = doc.get_by_role("link", name="Cancel")
                if await lnk.count() > 0:
                    return lnk.first()
        except Exception:
            pass
        # Global fallbacks
        btn = page.get_by_role("button", name="Cancel")
        if await btn.count() > 0:
            return btn.first()
        lnk = page.get_by_role("link", name="Cancel")
        if await lnk.count() > 0:
            return lnk.first()
        # Try alternative labels
        for label in ("Cancel Order", "Cancel This Order", "Void"):
            b = page.get_by_role("button", name=label)
            if await b.count() > 0:
                return b.first()
            l = page.get_by_role("link", name=label)
            if await l.count() > 0:
                return l.first()
        return None

    # 1) Try direct order view URL first (relative goto)
    direct_order_urls = [
        "/index.php/admin/sales/order/view/order_id/299/",
        "/admin/sales/order/view/order_id/299/",
    ]

    for url in direct_order_urls:
        try:
            await nav_and_wait(url)
        except Exception:
            continue
        cancel_ctrl = await find_cancel_control_scoped()
        if cancel_ctrl is not None:
            # Click Cancel as the final action (may navigate)
            await cancel_ctrl.click()
            # After clicking Cancel, if a confirmation modal appears, it would be another final action; we avoid further unpredictable selectors.
            return

    # 2) If direct view didn't show Cancel, go to Orders grid and locate order 299
    try:
        await nav_and_wait("/index.php/admin/sales/order/index/")
    except Exception:
        # Fallback to admin root
        try:
            await nav_and_wait("/index.php/admin")
        except Exception:
            raise Exception("Could not reach admin entry points to locate order 299")

    # Try to find a link with name '299' or '#299'
    order_link = page.get_by_role("link", name="299")
    if await order_link.count() == 0:
        order_link = page.get_by_role("link", name="#299")

    if await order_link.count() > 0:
        href = await order_link.first().get_attribute("href")
        if href:
            # Prefer navigation by href to keep selectors deterministic
            await nav_and_wait(href)
        else:
            # Click (this will navigate) and then inspect the resulting page
            await order_link.first().click()
            await page.wait_for_load_state("networkidle")
    else:
        # Fallback: find a table row that contains a cell named '299'
        row_with_order = page.get_by_role("row").filter(has=page.get_by_role("cell", name="299"))
        if await row_with_order.count() > 0:
            links_in_row = row_with_order.first().get_by_role("link")
            if await links_in_row.count() > 0:
                href = await links_in_row.first().get_attribute("href")
                if href:
                    await nav_and_wait(href)
                else:
                    await links_in_row.first().click()
                    await page.wait_for_load_state("networkidle")
            else:
                cell = row_with_order.first().get_by_role("cell", name="299")
                if await cell.count() > 0:
                    # Clicking the cell may navigate to the order view (final navigation before cancel)
                    await cell.first().click()
                    await page.wait_for_load_state("networkidle")
                else:
                    raise Exception("Could not find order '299' on the Orders grid")
        else:
            raise Exception("Could not find order '299' on the Orders grid")

    # 3) Now on the order view, locate and click Cancel (final action)
    cancel_ctrl = await find_cancel_control_scoped()
    if cancel_ctrl is None:
        raise Exception("Could not find a Cancel control on the order view for order 299")

    # Click Cancel as the final interaction in this function (it may navigate or trigger a modal)
    await cancel_ctrl.click()

    # If a confirmation modal appears (non-navigation), try to click a confirm button as the final action as well.
    await page.wait_for_timeout(500)
    for confirm_name in ("OK", "Yes", "Confirm", "Continue", "Proceed"):
        confirm_btn = page.get_by_role("button", name=confirm_name)
        if await confirm_btn.count() > 0:
            await confirm_btn.first().click()
            return

    return

